    return []; // Body is not a valid object
}

// Create a single output object that will contain all flattened properties
const flattenedOutput = {};

// Function to safely flatten object properties
function flattenObject(obj, prefix = '') {
    for (const [key, value] of Object.entries(obj)) {
        const newKey = prefix ? `${prefix}_${key}` : key;

        // Check if value is a non-null object (but not an array or Date)
        if (value && 
            typeof value === 'object' && 
            !Array.isArray(value) && 
            !(value instanceof Date) &&
            !(value instanceof RegExp)) {

            // If it's a nested object, flatten its properties
