// Recursive extractor to flatten everything
function extractFlat(obj, result = {}) {
  if (Array.isArray(obj)) {
    for (const item of obj) {
      if (typeof item === 'object' && item !== null) {
        extractFlat(item, result);
      } else {
        // Turn primitive array items into flags
        result[item] = true;
      }
    }
  } else if (typeof obj === 'object' && obj !== null) {
    for (const key in obj) {
      const value = obj[key];
      if (typeof value === 'object' && value !== null) {
        extractFlat(value, result);
      } else {
        result[key] = value;
      }
    }
  }
  return result;
}

let final = {};
for (const key in input) {
