// Ultra-efficient extraction of the latest toolCallId from webhook payload

try {
  // Direct access to toolCalls array from webhook
  const toolCalls = $('Webhook').first().json.body.message.toolCalls;

  // Fast validation and extraction
  if (!Array.isArray(toolCalls) || toolCalls.length === 0) {
    return [{
      json: {
        latestToolCallId: null,
        error: 'No toolCalls found or empty array',
        totalToolCalls: 0,
        extractedAt: new Date().toISOString()
      }
    }];
  }

  // Get the latest (last) toolCall - most efficient approach
  const latestIndex = toolCalls.length - 1;
  const latestToolCall = toolCalls[latestIndex];

  // Extract the ID with validation
  const latestToolCallId = latestToolCall?.id || null;

  if (!latestToolCallId) {
    return [{
      json: {
        latestToolCallId: null,
        error: `ToolCall at index ${latestIndex} missing id property`,
        totalToolCalls: toolCalls.length,
        latestIndex: latestIndex,
        extractedAt: new Date().toISOString()
      }
    }];
  }

  // Success - return the latest toolCallId
  return [{
    json: {
      latestToolCallId: latestToolCallId,
      latestIndex: latestIndex,
      totalToolCalls: toolCalls.length,
      extractedAt: new Date().toISOString()
    }
  }];

} catch (error) {
  // Error handling
  return [{
    json: {
      latestToolCallId: null,
      error: `Extraction failed: ${error.message}`,
      totalToolCalls: 0,
      extractedAt: new Date().toISOString()
    }
  }];
}

