// n8n Code node (JavaScript)

// Robust recursive flattener: only leaf values
const flattenObject = (obj, parentKey = '') => {
  const result = {};

  const walk = (value, keyPath) => {
    if (Array.isArray(value)) {
      value.forEach((el, idx) => {
        const nextPath = keyPath ? `${keyPath}[${idx}]` : `[${idx}]`;
        if (el !== null && typeof el === 'object') {
          walk(el, nextPath);
        } else {
          result[nextPath] = el;
        }
      });
      return;
    }

    if (value !== null && typeof value === 'object') {
      for (const k in value) {
        if (!Object.prototype.hasOwnProperty.call(value, k)) continue;
        const v = value[k];
        const nextPath = keyPath ? `${keyPath}.${k}` : k;
        walk(v, nextPath);
      }
      return;
    }

    if (keyPath) result[keyPath] = value;
  };

  walk(obj, parentKey);
  return result;
};

return items.map(item => {
  const body = item?.json?.body;

  // Always return exactly two fields: combined and checkInPreferencesCombined
  if (!body || typeof body !== 'object') {
    return { json: { combined: "", checkInPreferencesCombined: "" } };
  }

  // 1) Original combined: flatten entire body
  const flattenedAll = flattenObject(body);
  const combined = Object.entries(flattenedAll)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ');

  // 2) Group checkInPreferences into one variable only (no individual keys)
  const prefs = body?.onboardingData?.checkInPreferences;
  const checkInPreferencesCombined = Array.isArray(prefs)
    ? prefs.join(', ')
    : "";

  // Critically: do NOT spread any individual checkInPreferences[...] keys
  // Only return the grouped field alongside combined
  return { json: { combined, checkInPreferencesCombined } };
});

